    lv_theme_t *theme = lv_theme_simple_init(dispp);
    lv_disp_set_theme(dispp, theme);

    /* ── Force default screen to solid black AFTER theme init ──────── */
    /* lv_theme_simple_init sets the default screen background to white.
     * We must override it AFTER the theme, otherwise the theme's local
     * style (white) overrides ours (black).  This is the THIRD and
     * final line of defense against the white flash. */
    lv_obj_t *def_scr = lv_display_get_screen_active(dispp);
    lv_obj_set_style_bg_color(def_scr, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(def_scr, LV_OPA_COVER, 0);

    /* ── 1. Create & show boot-up screen FIRST (unless skipped) ────── */
    if (!g_config.skip_boot_screen) {
        ui_boot_up_screen_init();
        ui_boot_up_start_animation();
        lv_disp_load_scr(ui_boot_up);

        /* Render ONE frame of the boot screen NOW.  WiFi will block the
         * main task for seconds; without this the display shows a frozen
         * default-screen (black) until the main loop starts.  One
         * lv_timer_handler pass renders the boot screen to the frame-
         * buffer and the QSPI display latches it. */
        lv_timer_handler_run_in_period(50);
    }

    /* ── 2. Create other screens in background ──────────────────────── */
    ui_charging_screen_init();

    /* ── 2b. Watch-face registry: register faces and prepare the saved
     * face's screen OFF-SCREEN (boot-up screen stays visible). ─────── */
